});

const respBody = pm.response.json();
const usuarioIdReal = respBody.data.usuario_id;

pm.test('La respuesta confirma tipo_evento password_reset_solicitado', function () {
  pm.expect(respBody.data.tipo_evento).to.eql('password_reset_solicitado');
});

const sqlBody = {
  sql: "SELECT COUNT(*) as total FROM qa_training.sesiones WHERE usuario_id = $1 AND tipo_evento = $2",
  params: [usuarioIdReal, 'password_reset_solicitado']
};

pm.sendRequest({
  url: pm.variables.get('baseUrl') + '/api/v1/sql/select',
  method: 'POST',
  header: { 'Content-Type': 'application/json', 'x-api-key': pm.variables.get('apiKey') },
  body: { mode: 'raw', raw: JSON.stringify(sqlBody) }
}, function (err, res) {
  if (err) { console.error('Error en post-request:', err); return; }
  const total = parseInt(res.json().data[0].total, 10);
  console.log('usuario_id real (de la respuesta):', usuarioIdReal, '| eventos en BD:', total);

  pm.test('El evento password_reset_solicitado quedó persistido en BD', function () {
    pm.expect(total).to.be.above(0);
  });
});

const sqlBody = {
  sql: "SELECT id, email FROM qa_training.usuarios WHERE activo = $1 ORDER BY random() LIMIT 1",
  params: [true]
};

pm.sendRequest({
  url: pm.variables.get('baseUrl') + '/api/v1/sql/select',
  method: 'POST',
  header: { 'Content-Type': 'application/json', 'x-api-key': pm.variables.get('apiKey') },
  body: { mode: 'raw', raw: JSON.stringify(sqlBody) }
}, function (err, res) {
  if (err) { console.error('Error en pre-request (usuario):', err); return; }
  const body = res.json();
  if (!body.data || body.data.length === 0) {
    console.error('No se encontró usuario activo en qa_training.usuarios');
    return;
  }
  const usuario = body.data[0];
  pm.collectionVariables.set('emailRegistrado', usuario.email);
  pm.collectionVariables.set('usuarioIdRegistrado', usuario.id);

  const countBody = {
    sql: "SELECT COUNT(*) as total FROM qa_training.sesiones WHERE usuario_id = $1 AND tipo_evento = $2",
    params: [usuario.id, 'password_reset_solicitado']
  };

  pm.sendRequest({
    url: pm.variables.get('baseUrl') + '/api/v1/sql/select',
    method: 'POST',
    header: { 'Content-Type': 'application/json', 'x-api-key': pm.variables.get('apiKey') },
    body: { mode: 'raw', raw: JSON.stringify(countBody) }
  }, function (err2, res2) {
    if (err2) { console.error('Error en pre-request (baseline):', err2); return; }
    const baseline = parseInt(res2.json().data[0].total, 10);
    pm.collectionVariables.set('baselineCount', baseline);
    console.log('Usuario:', usuario, '| baseline password_reset_solicitado:', baseline);
  });
});

